// Differential harness: run the frozen Python executable and the Node port on
// the same argv and report any divergence.
//
// Usage:
//   node /tmp/harness/diff.mjs '<json-array-of-argv>'          # one case
//   node /tmp/harness/diff.mjs --file cases.json               # many cases
//
// cases.json is a JSON array whose entries are either argv arrays or
// {name, argv} objects. Exit status is 1 if any case diverged.
//
// Argv entries may use \uXXXX escapes to carry arbitrary characters. A NUL
// byte cannot survive execve(), so such cases are skipped.

import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const PY = '/workspace/dataset/test6_executable';
const JS = '/output/test6.mjs';

// The PyInstaller banner embeds the pid, which necessarily differs run to run.
function normalise(text) {
  return text.replace(/\[PYI-\d+:/g, '[PYI-N:');
}

function run(command, argv) {
  const result = spawnSync(command[0], [...command.slice(1), ...argv], {
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024,
  });
  return {
    status: result.status,
    stdout: result.stdout ?? '',
    stderr: normalise(result.stderr ?? ''),
  };
}

function hasNul(token) {
  for (let i = 0; i < token.length; i += 1) {
    if (token.charCodeAt(i) === 0) return true;
  }
  return false;
}

function describe(argv) {
  return argv.map((token) => JSON.stringify(token)).join(' ');
}

const [first, second] = process.argv.slice(2);
const cases =
  first === '--file' ? JSON.parse(readFileSync(second, 'utf8')) : [JSON.parse(first)];

let failures = 0;
let skipped = 0;
for (const entry of cases) {
  const argv = Array.isArray(entry) ? entry : entry.argv;
  const name = Array.isArray(entry) ? describe(argv) : entry.name;
  if (argv.some(hasNul)) {
    skipped += 1;
    console.log(`SKIP  ${name}  (NUL cannot pass through execve)`);
    continue;
  }
  const py = run([PY], argv);
  const js = run(['node', JS], argv);
  if (py.status === js.status && py.stdout === js.stdout && py.stderr === js.stderr) continue;
  failures += 1;
  console.log(`FAIL  ${name}`);
  console.log(`  argv: ${describe(argv)}`);
  console.log(`  py  rc=${py.status} out=${JSON.stringify(py.stdout)} err=${JSON.stringify(py.stderr)}`);
  console.log(`  js  rc=${js.status} out=${JSON.stringify(js.stdout)} err=${JSON.stringify(js.stderr)}`);
}
console.log(`\n${cases.length - failures - skipped}/${cases.length} matched, ${failures} failed, ${skipped} skipped`);
process.exit(failures > 0 ? 1 : 0);

1	// An ArgumentParser faithful to argparse for a parser built from optional
2	// arguments only — the shape the source script uses.
3	
4	import { ArgumentError, ArgumentParserError } from './errors.mjs';
5	import { formatUsage, formatHelp } from './formatter.mjs';
6	import { SystemExit } from '../python/errors.mjs';
7	import { reprStr } from '../python/repr.mjs';
8	import { writeStdout, writeStderr } from '../python/sys.mjs';
9	
10	// A token that merely looks like a negative number is treated as a value, not
11	// an option — provided no option string itself looks numeric.
12	const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;
13	
14	class Action {
15	  constructor(spec) {
16	    Object.assign(this, spec);
17	  }
18	
19	  // How argparse names an action in error messages: every option string it
20	  // answers to, joined by slashes.
21	  get name() {
22	    return this.optionStrings.join('/');
23	  }
24	}
25	
26	export class ArgumentParser {
27	  constructor({ prog, addHelp = true } = {}) {
28	    this.prog = prog;
29	    this.actions = [];
30	    this.optionMap = new Map();
31	    if (addHelp) {
32	      this.addAction({
33	        optionStrings: ['-h', '--help'],
34	        dest: null,
35	        metavar: null,
36	        type: null,
37	        required: false,
38	        takesValue: false,
39	        help: 'show this help message and exit',
40	        isHelp: true,
41	      });
42	    }
43	  }
44	
45	  addAction(spec) {
46	    const action = new Action(spec);
47	    this.actions.push(action);
48	    for (const option of action.optionStrings) this.optionMap.set(option, action);
49	    return action;
50	  }
51	
52	  // add_argument for a single long option, e.g. ('--a', {type: INT_TYPE}).
53	  addArgument(optionString, { type, required = false, help = null } = {}) {
54	    const dest = optionString.replace(/^--?/, '').replace(/-/g, '_');
55	    return this.addAction({
56	      optionStrings: [optionString],
57	      dest,
58	      metavar: dest.toUpperCase(),
59	      type,
60	      required,
61	      takesValue: true,
62	      help,
63	      isHelp: false,
64	    });
65	  }
66	
67	  // Whether a raw token should be read as an option, a plain value, or the
68	  // "--" end-of-options marker.
69	  classifyToken(token) {
70	    if (token === '') return 'value';
71	    if (!token.startsWith('-')) return 'value';
72	    if (token === '-') return 'value';
73	    if (token === '--') return 'separator';
74	    if (NEGATIVE_NUMBER.test(token)) return 'value';
75	    if (token.includes(' ')) return 'value';
76	    return 'option';
77	  }
78	
79	  // Long options may be abbreviated to any unambiguous prefix.
80	  matchPrefix(prefix) {
81	    const matches = [];
82	    for (const [option, action] of this.optionMap) {
83	      if (option.startsWith('--') && option.startsWith(prefix)) matches.push({ option, action });
84	    }
85	    if (matches.length === 0) return null;
86	    const distinct = new Set(matches.map((entry) => entry.action));
87	    if (distinct.size > 1) {
88	      const names = matches.map((entry) => entry.option).join(', ');
89	      throw new ArgumentParserError(`ambiguous option: ${prefix} could match ${names}`);
90	    }
91	    return matches[0].action;
92	  }
93	
94	  // Splits one option token into the action it names, any value attached with
95	  // "=" or packed after a short flag, and the remainder of a short cluster.
96	  splitOption(token) {
97	    const exact = this.optionMap.get(token);
98	    if (exact) return { action: exact, explicit: null, rest: null };
99	
100	    if (token.startsWith('--')) {
101	      const separatorAt = token.indexOf('=');
102	      if (separatorAt > -1) {
103	        const head = token.slice(0, separatorAt);
104	        const action = this.optionMap.get(head) ?? this.matchPrefix(head);
105	        if (!action) return { action: null };
106	        return { action, explicit: token.slice(separatorAt + 1), rest: null };
107	      }
108	      const action = this.matchPrefix(token);
109	      return action ? { action, explicit: null, rest: null } : { action: null };
110	    }
111	
112	    // Single dash: peel the two-character flag off the front of the cluster.
113	    const head = token.slice(0, 2);
114	    const action = this.optionMap.get(head);
115	    if (!action) return { action: null };
116	    const tail = token.slice(2);
117	    if (action.takesValue) return { action, explicit: tail === '' ? null : tail, rest: null };
118	    return { action, explicit: null, rest: tail === '' ? null : `-${tail}` };
119	  }
120	
121	  convert(action, text) {
122	    const value = action.type.convert(text);
123	    if (value === null) {
124	      throw new ArgumentError(action.name, `invalid ${action.type.name} value: ${reprStr(text)}`);
125	    }
126	    return value;
127	  }
128	
129	  // Consumes the option token at `index`, returning the next index to read.
130	  consumeOption(argv, index, namespace, seen, extras) {
131	    const token = argv[index];
132	    let pending = token;
133	
134	    while (pending !== null) {
135	      const { action, explicit, rest } = this.splitOption(pending);
136	      if (!action) {
137	        // Unknown options are collected whole and reported after parsing.
138	        extras.push(token);
139	        return index + 1;
140	      }
141	
142	      if (action.takesValue) {
143	        if (explicit !== null) {
144	          namespace[action.dest] = this.convert(action, explicit);
145	          seen.add(action);
146	          return index + 1;
147	        }
148	        const next = index + 1 < argv.length ? argv[index + 1] : null;
149	        if (next === null || this.classifyToken(next) !== 'value') {
150	          throw new ArgumentError(action.name, 'expected one argument');
151	        }
152	        namespace[action.dest] = this.convert(action, next);
153	        seen.add(action);
154	        return index + 2;
155	      }
156	
157	      if (explicit !== null) {
158	        throw new ArgumentError(action.name, `ignored explicit argument ${reprStr(explicit)}`);
159	      }
160	      // Flags fire the moment they are reached, before any later token — and
161	      // before the required-argument check.
162	      if (action.isHelp) this.printHelpAndExit();
163	      pending = rest;
164	    }
165	    return index + 1;
166	  }
167	
168	  parseArgs(argv) {
169	    const namespace = {};
170	    for (const action of this.actions) {
171	      if (action.dest) namespace[action.dest] = null;
172	    }
173	
174	    const seen = new Set();
175	    const extras = [];
176	    let index = 0;
177	    let afterSeparator = false;
178	
179	    while (index < argv.length) {
180	      const token = argv[index];
181	      if (afterSeparator) {
182	        extras.push(token);
183	        index += 1;
184	        continue;
185	      }
186	      const kind = this.classifyToken(token);
187	      if (kind === 'value') {
188	        extras.push(token);
189	        index += 1;
190	      } else if (kind === 'separator') {
191	        // With no positionals declared, "--" is never absorbed; it stays in
192	        // the leftovers and everything after it is a plain value.
193	        extras.push(token);
194	        afterSeparator = true;
195	        index += 1;
196	      } else {
197	        index = this.consumeOption(argv, index, namespace, seen, extras);
198	      }
199	    }
200	
201	    const missing = this.actions
202	      .filter((action) => action.required && !seen.has(action))
203	      .map((action) => action.name);
204	    if (missing.length > 0) {
205	      throw new ArgumentParserError(
206	        `the following arguments are required: ${missing.join(', ')}`,
207	      );
208	    }
209	    if (extras.length > 0) {
210	      throw new ArgumentParserError(`unrecognized arguments: ${extras.join(' ')}`);
211	    }
212	    return namespace;
213	  }
214	
215	  printHelpAndExit() {
216	    writeStdout(formatHelp(this));
217	    throw new SystemExit(0);
218	  }
219	
220	  // parser.error(): usage plus the message on stderr, then exit status 2.
221	  error(message) {
222	    writeStderr(formatUsage(this));
223	    writeStderr(`${this.prog}: error: ${message}\n`);
224	    throw new SystemExit(2);
225	  }
226	}
227	
228	export { ArgumentError, ArgumentParserError };
