1	// Usage and help text layout, reproducing argparse's HelpFormatter output for
2	// a parser made up entirely of optional arguments.
3	
4	const INDENT = '  ';
5	const MAX_HELP_POSITION = 24;
6	
7	// In usage, an action appears under its first option string only, wrapped in
8	// brackets unless it is required.
9	function usageFragment(action) {
10	  const core = action.takesValue
11	    ? `${action.optionStrings[0]} ${action.metavar}`
12	    : action.optionStrings[0];
13	  return action.required ? core : `[${core}]`;
14	}
15	
16	export function formatUsage(parser) {
17	  const fragments = parser.actions.map(usageFragment);
18	  return `usage: ${[parser.prog, ...fragments].join(' ')}\n`;
19	}
20	
21	// In the options list every option string is shown, so the help action reads
22	// "-h, --help" rather than just "-h".
23	function helpInvocation(action) {
24	  if (!action.takesValue) return action.optionStrings.join(', ');
25	  return action.optionStrings.map((option) => `${option} ${action.metavar}`).join(', ');
26	}
27	
28	export function formatHelp(parser) {
29	  const invocations = parser.actions.map(helpInvocation);
30	
31	  // argparse aligns help text one column past the widest invocation, capped so
32	  // a single long option cannot push every description off to the right.
33	  const widest = Math.max(0, ...invocations.map((text) => text.length + INDENT.length));
34	  const helpPosition = Math.min(widest + 2, MAX_HELP_POSITION);
35	
36	  let out = formatUsage(parser);
37	  out += '\noptions:\n';
38	  parser.actions.forEach((action, index) => {
39	    const invocation = invocations[index];
40	    if (!action.help) {
41	      out += `${INDENT}${invocation}\n`;
42	      return;
43	    }
44	    const written = INDENT.length + invocation.length;
45	    // A description that would collide with its own invocation starts on the
46	    // next line instead; otherwise it is padded out to the help column.
47	    if (written + 2 > helpPosition) {
48	      out += `${INDENT}${invocation}\n${' '.repeat(helpPosition)}${action.help}\n`;
49	    } else {
50	      out += `${INDENT}${invocation}${' '.repeat(helpPosition - written)}${action.help}\n`;
51	    }
52	  });
53	  return out;
54	}
