     1	// int(str) with CPython's decimal-literal grammar.
     2	
     3	import { isDecimalDigit, decimalDigitValue, isIntWhitespace } from '../unicode/properties.mjs';
     4	
     5	// Accepts surrounding whitespace, one optional sign, a run of Unicode Nd
     6	// digits, and underscores only *between* digits. Returns a BigInt, or null
     7	// when the text is not a valid literal — int() has no size limit, so neither
     8	// does this.
     9	export function pyInt(text) {
    10	  const chars = Array.from(text);
    11	  let start = 0;
    12	  let end = chars.length;
    13	  while (start < end && isIntWhitespace(chars[start])) start += 1;
    14	  while (end > start && isIntWhitespace(chars[end - 1])) end -= 1;
    15	
    16	  let negative = false;
    17	  if (start < end && (chars[start] === '+' || chars[start] === '-')) {
    18	    negative = chars[start] === '-';
    19	    start += 1;
    20	  }
    21	
    22	  let digits = '';
    23	  let afterDigit = false;
    24	  for (let index = start; index < end; index += 1) {
    25	    const ch = chars[index];
    26	    if (ch === '_') {
    27	      // A separator is only legal once a digit has been seen, and never twice
    28	      // in a row — which also rejects a leading underscore.
    29	      if (!afterDigit) return null;
    30	      afterDigit = false;
    31	      continue;
    32	    }
    33	    if (!isDecimalDigit(ch)) return null;
    34	    digits += String(decimalDigitValue(ch));
    35	    afterDigit = true;
    36	  }
    37	  // False here means no digits at all, or a trailing underscore.
    38	  if (!afterDigit) return null;
    39	
    40	  const magnitude = BigInt(digits);
    41	  return negative ? -magnitude : magnitude;
    42	}
